#include "tmr_irq_private.h"
/*==========================================================================*/
/*      D E F I N E S  -  E N U M E R A T I O N S  -  T Y P E D E F S       */
/*==========================================================================*/

/*==========================================================================*/
/*                  F U N C T I O N   P R O T O T Y P E S                   */
/*==========================================================================*/

/*==========================================================================*/
/*                            V A R I A B L E S                             */
/*==========================================================================*/
static Boolean do_one_time = TRUE ; 
/*==========================================================================*/
/*                 F U N C T I O N   D E F I N I T I O N S                  */
/*==========================================================================*/

/*--------------------------------------------------------------------------*/

void tmr_irq_init (void)
{
	if( do_one_time )
	{
		PCONP |= (1u << 23) ;		// POWER the TIMER
	
		PCLKSEL1 &= ~(3u << 14) ;
		PCLKSEL1 |=  (1u << 14) ;   // Divide CPU clock by 1
	
		T3PR   = 0x00000000 ;       // Set prescaler to divide by 1
	       
		T3TCR  = 0x01 ;             // Enable TIMER
	
		/// Hook into VIC interrupt controller ///
		isr_set_vector (ISR_ID_TIMER_3 , ISR_PRI_15 , ISR_TYPE_IRQ_FAST , tmr_irq_service) ;	
	
		tmr_irq_count = 0 ; 

		ATOMIC( do_one_time = FALSE );
	}
}

/*--------------------------------------------------------------------------*/

